// 0x10b3 sort_traverse_roche : 10 : +0x18 bit 0x20 (ou 0x80), passer à travers un mur au prochain déplacement
function sort_traverse_roche_10b3(m, ip) {
  for (;;) {
    if (m.pas <= 0) return ip;
    switch (ip) {
      case 0x10b3: m.t += 3; m.pas -= 3; m.bx = 0x5a;  // mov bx, 0x5a
      case 0x10b6: m.sub8(m.rb(m.ds, 0x3fa7), 0x3);  // cmp byte ptr [0x3fa7], 3
      case 0x10bb: if (!m.zf) { ip = 0x10cb; continue; }  // jne 0x10cb
      case 0x10bd: m.t += 3; m.pas -= 3; m.ax = (m.ax & 0xff00) | m.rb(m.ds, 0x3f9b);  // mov al, byte ptr [0x3f9b]
      case 0x10c0: m.and8((m.ax & 0xff), 0x1);  // test al, 1
      case 0x10c2: if (m.zf) { ip = 0x10cb; continue; }  // je 0x10cb
      case 0x10c4: m.t += 2; m.pas -= 2; m.wb(m.ds, ((m.si + 0x18) & 0xffff), m.or8(m.rb(m.ds, ((m.si + 0x18) & 0xffff)), 0x80));  // or byte ptr [si + 0x18], 0x80
      case 0x10c8: ip = 0x0f6d; continue;  // jmp 0xf6d
      case 0x10cb: m.t += 2; m.pas -= 2; m.wb(m.ds, ((m.si + 0x18) & 0xffff), m.or8(m.rb(m.ds, ((m.si + 0x18) & 0xffff)), 0x20));  // or byte ptr [si + 0x18], 0x20
      case 0x10cf: ip = 0x0f6d; continue;  // jmp 0xf6d
      case 0x10d2: m.t += 1; m.pas -= 1; m.push(0x10d5); ip = 0x10d8; continue;  // call 0x10d8
      case 0x10d5: m.t += 1; m.pas -= 1; ip = 0x12aa; continue;  // jmp 0x12aa
      default: return ip;
    }
  }
}

// 0x10d8 mort_heros : fiche SI : points de corps, or, équipement et artefacts à zéro, sort de la quête ; « VOUS AVEZ ESSUYE DES BLESSURES MORTELLES »
function mort_heros_10d8(m, ip) {
  for (;;) {
    if (m.pas <= 0) return ip;
    switch (ip) {
      case 0x10d8: m.t += 10; m.pas -= 10; m.wb(m.ds, ((m.si + 0x6) & 0xffff), 0x0);  // mov byte ptr [si + 6], 0
      case 0x10dc: m.wb(m.ds, m.si, 0x0);  // mov byte ptr [si], 0
      case 0x10df: m.wb(m.ds, ((m.si + 0xe) & 0xffff), 0x0);  // mov byte ptr [si + 0xe], 0
      case 0x10e3: m.wb(m.ds, ((m.si + 0xf) & 0xffff), 0x0);  // mov byte ptr [si + 0xf], 0
      case 0x10e7: m.wb(m.ds, ((m.si + 0xd) & 0xffff), 0x0);  // mov byte ptr [si + 0xd], 0
      case 0x10eb: m.ww(m.ds, ((m.si + 0x9) & 0xffff), 0x0);  // mov word ptr [si + 9], 0
      case 0x10f0: m.wb(m.ds, ((m.si + 0x11) & 0xffff), 0x0);  // mov byte ptr [si + 0x11], 0
      case 0x10f4: m.wb(m.ds, ((m.si + 0x12) & 0xffff), 0x0);  // mov byte ptr [si + 0x12], 0
      case 0x10f8: m.wb(m.ds, ((m.si + 0x13) & 0xffff), 0x0);  // mov byte ptr [si + 0x13], 0
      case 0x10fc: m.push(0x10ff); ip = 0x26e2; continue;  // call 0x26e2
      case 0x10ff: m.t += 2; m.pas -= 2; m.bx = 0x20;  // mov bx, 0x20
      case 0x1102: m.push(0x1105); ip = 0x88ed; continue;  // call 0x88ed
      case 0x1105: m.t += 1; m.pas -= 1; m.push(0x1108); ip = 0x1825; continue;  // call 0x1825
      case 0x1108: m.t += 3; m.pas -= 3; m.ax = (m.ax & 0xff00) | m.rb(m.ds, 0x3fa7);  // mov al, byte ptr [0x3fa7]
      case 0x110b: m.sub8((m.ax & 0xff), m.rb(m.ds, 0x3fca));  // cmp al, byte ptr [0x3fca]
      case 0x110f: if (!m.zf) { ip = 0x1116; continue; }  // jne 0x1116
      case 0x1111: m.t += 1; m.pas -= 1; m.wb(m.ds, 0x3f9a, 0x1);  // mov byte ptr [0x3f9a], 1
      case 0x1116: m.t += 1; m.pas -= 1; m.push(0x1119); ip = 0x06b4; continue;  // call 0x6b4
      case 0x1119: m.t += 1; m.pas -= 1; if (!m.zf) { ip = 0x1124; continue; }  // jne 0x1124
      case 0x111b: m.t += 2; m.pas -= 2; m.bx = 0x1e;  // mov bx, 0x1e
      case 0x111e: m.push(0x1121); ip = 0x88ed; continue;  // call 0x88ed
      case 0x1121: m.t += 1; m.pas -= 1; m.push(0x1124); ip = 0x1825; continue;  // call 0x1825
        ip = 0x1124; continue;
      default: return ip;
    }
  }
}

