// 0x1a35 message_puis_sortie : affiche le message SI, puis apres_sortie
function message_puis_sortie_1a35(m, ip) {
  for (;;) {
    if (m.pas <= 0) return ip;
    switch (ip) {
      case 0x1a35: m.t += 2; m.pas -= 2; m.bx = m.si;  // mov bx, si
      case 0x1a37: m.push(0x1a3a); ip = 0x88ed; continue;  // call 0x88ed
        ip = 0x1a3a; continue;
      default: return ip;
    }
  }
}

// 0x1a3a apres_sortie : « LES JOUEURS SONT TOUS ELIMINES » si plus aucun héros dans la quête
function apres_sortie_1a3a(m, ip) {
  for (;;) {
    if (m.pas <= 0) return ip;
    switch (ip) {
      case 0x1a3a: m.t += 1; m.pas -= 1; m.push(0x1a3d); ip = 0x1825; continue;  // call 0x1825
      case 0x1a3d: m.t += 1; m.pas -= 1; m.push(0x1a40); ip = 0x06b4; continue;  // call 0x6b4
      case 0x1a40: m.t += 2; m.pas -= 2; m.ax = (m.ax & 0xff00) | m.or8((m.ax & 0xff), (m.ax & 0xff));  // or al, al
      case 0x1a42: if (!m.zf) { ip = 0x1a4a; continue; }  // jne 0x1a4a
      case 0x1a44: m.t += 2; m.pas -= 2; m.bx = 0x1e;  // mov bx, 0x1e
      case 0x1a47: m.push(0x1a4a); ip = 0x88ed; continue;  // call 0x88ed
      case 0x1a4a: m.t += 1; m.pas -= 1; m.push(0x1a4d); ip = 0x665e; continue;  // call 0x665e
      case 0x1a4d: m.t += 1; m.pas -= 1; ip = 0x6eaa; continue;  // jmp 0x6eaa
      default: return ip;
    }
  }
}

// 0x1a50 dessine_carte : parchemin MAPS 256 × 197 en (32, 2), puis grille 26 × 19 de tuiles 8 × 8 depuis (56, 16) : sols, murs, bords droit (tuile 0x22) et bas (0x21), occupants, puis les 5 personnages (icône DS:52A1 par type)
