// 0x4571 affiche_hexa : DX en 4 chiffres hexadécimaux
function affiche_hexa_4571(m, ip) {
  for (;;) {
    if (m.pas <= 0) return ip;
    switch (ip) {
      case 0x4571: m.t += 3; m.pas -= 3; m.ww(m.ds, 0x37f3, m.dx);  // mov word ptr [0x37f3], dx
      case 0x4575: m.ax = (m.ax & 0xff00) | (m.dx >> 8);  // mov al, dh
      case 0x4577: m.push(0x457a); ip = 0x4595; continue;  // call 0x4595
      case 0x457a: m.t += 3; m.pas -= 3; m.ax = m.rw(m.ds, 0x37f3);  // mov ax, word ptr [0x37f3]
      case 0x457d: m.ax = (m.ax & 0xff00) | (m.ax >> 8);  // mov al, ah
      case 0x457f: m.push(0x4582); ip = 0x458f; continue;  // call 0x458f
      case 0x4582: m.t += 2; m.pas -= 2; m.ax = m.rw(m.ds, 0x37f3);  // mov ax, word ptr [0x37f3]
      case 0x4585: m.push(0x4588); ip = 0x4595; continue;  // call 0x4595
      case 0x4588: m.t += 2; m.pas -= 2; m.ax = m.rw(m.ds, 0x37f3);  // mov ax, word ptr [0x37f3]
      case 0x458b: m.push(0x458e); ip = 0x458f; continue;  // call 0x458f
      case 0x458e: m.t += 1; m.pas -= 1; ip = m.pop(); continue;  // ret
      default: return ip;
    }
  }
}

// 0x458f chiffre_hexa_bas : chiffre du quartet bas de AL
