// 0x58b5 restaure_tampon : inverse de sauve_tampon : recopie le segment DS:5E35 dans le tampon (64 000 octets en VGA, 32 000 sinon)
function restaure_tampon_58b5(m, ip) {
  for (;;) {
    if (m.pas <= 0) return ip;
    switch (ip) {
      case 0x58b5: m.t += 7; m.pas -= 7; m.push(m.ax);  // push ax
      case 0x58b6: m.ax = ((0x1463 + m.L) & 0xffff);  // mov ax, 0x1463
      case 0x58b9: m.es = m.ax;  // mov es, ax
      case 0x58bb: { const t = m.pop(); m.ax = t; }  // pop ax
      case 0x58bc: m.cx = 0x7d00;  // mov cx, 0x7d00
      case 0x58bf: m.sub16(m.rw(m.ds, 0x3190), 0x8);  // cmp word ptr [0x3190], 8
      case 0x58c4: if (m.zf) { ip = 0x58c8; continue; }  // je 0x58c8
      case 0x58c6: m.t += 1; m.pas -= 1; m.cx = m.shr16(m.cx, 0x1);  // shr cx, 1
      case 0x58c8: m.t += 12; m.pas -= 12; m.push(m.ax);  // push ax
      case 0x58c9: m.ax = m.rw(m.ds, 0x5e35);  // mov ax, word ptr [0x5e35]
      case 0x58cc: m.ds = m.ax;  // mov ds, ax
      case 0x58ce: { const t = m.pop(); m.ax = t; }  // pop ax
      case 0x58cf: m.di = 0x0;  // mov di, 0
      case 0x58d2: m.si = 0x0;  // mov si, 0
      case 0x58d5: m.movsw(m.ds, 1);  // rep movsw word ptr es:[di], word ptr [si]
      case 0x58d7: m.push(m.ax);  // push ax
      case 0x58d8: m.ax = ((0x97c + m.L) & 0xffff);  // mov ax, 0x97c
      case 0x58db: m.ds = m.ax;  // mov ds, ax
      case 0x58dd: { const t = m.pop(); m.ax = t; }  // pop ax
      case 0x58de: ip = m.pop(); continue;  // ret
      default: return ip;
    }
  }
}

