// 0x5ab1 icones_etat : met CX icônes à partir de DI à l'état AL, à redessiner
function icones_etat_5ab1(m, ip) {
  for (;;) {
    if (m.pas <= 0) return ip;
    switch (ip) {
      case 0x5ab1: m.t += 4; m.pas -= 4; m.wb(m.ds, ((m.di + 0x7) & 0xffff), 0x1);  // mov byte ptr [di + 7], 1
      case 0x5ab5: m.wb(m.ds, ((m.di + 0x6) & 0xffff), (m.ax & 0xff));  // mov byte ptr [di + 6], al
      case 0x5ab8: m.di = m.add16(m.di, 0xc);  // add di, 0xc
      case 0x5abb: m.cx = (m.cx - 1) & 0xffff; if (m.cx !== 0) { ip = 0x5ab1; continue; }  // loop 0x5ab1
      case 0x5abd: m.t += 1; m.pas -= 1; ip = m.pop(); continue;  // ret
      default: return ip;
    }
  }
}

